package dev.gbppimentel.zzz;
import java.nio.file.*;import java.io.*;import java.awt.image.BufferedImage;import javax.imageio.ImageIO;import org.json.*;
public final class ContextTest{public static void main(String[] args)throws Exception{int n=0;String text=Files.readString(Path.of("assets/combat-catalog.json"));ContextParser p=new ContextParser(text);if(!ContextParser.uid("UID: 1000000001 11").equals("1000000001"))throw new AssertionError("UID parse");n++;if(!ContextParser.uid("13004362 04").isEmpty())throw new AssertionError("Broken UID cannot verify account");n++;ContextParser.Identity id=new ContextParser.Identity();if(id.update("1000000001"))throw new AssertionError("One frame cannot open account");n++;if(!id.update("1000000001"))throw new AssertionError("Stable UID must open account");n++;id.update("1000000000");if(!id.confirmed.equals("1000000001"))throw new AssertionError("One OCR mistake must preserve verified identity");id.update("1000000000");id.update("1000000000");if(!id.confirmed.equals("1000000000"))throw new AssertionError("Repeated account change must replace verification");n++;for(int i=0;i<50;i++)id.update("");if(!id.confirmed.equals("1000000000"))throw new AssertionError("Hidden UID cannot expire a verified game session");n++;id.clear();if(!id.candidate.isEmpty()||!id.confirmed.isEmpty())throw new AssertionError("Game close must reset identity");n++;if(p.enemy("random letters from UI")!=null)throw new AssertionError("Unmatched enemy must stay unknown");n++;if(!p.agent("Phoenix Command List").equals("1641"))throw new AssertionError("Agent text parse");n++;
 PortraitMatcher matcher=new PortraitMatcher(Files.readString(Path.of("assets/portraits.json")));BufferedImage originalCombat=ImageIO.read(new File("private/calibration/combat.png"));JSONArray originalSquad=matcher.find(originalCombat.getRGB(0,0,originalCombat.getWidth(),originalCombat.getHeight(),null,0,originalCombat.getWidth()),originalCombat.getWidth(),originalCombat.getHeight(),"combat");System.out.println("Independent older capture: "+originalSquad);if(originalSquad.length()!=3||!originalSquad.getJSONObject(0).getString("id").equals("1611"))throw new AssertionError("Public catalog must recognize older holdout capture without captured identity samples");n++;
 for(String[] c:new String[][]{{"bugs-combat.png","1211"},{"bugs-combat2.png","1211"},{"bugs-combat3.png","1101"},{"bugs-combat4.png","1611"}}){BufferedImage im=ImageIO.read(new File("private/calibration/"+c[0]));JSONArray a=matcher.find(im.getRGB(0,0,im.getWidth(),im.getHeight(),null,0,im.getWidth()),im.getWidth(),im.getHeight(),"combat");System.out.println(c[0]+": "+a);if(a.length()!=3||!a.getJSONObject(0).getString("id").equals(c[1]))throw new AssertionError("Squad and on-field calibration "+c[0]);n++;}
 for(String file:new String[]{"bugs-combat.png","bugs-combat2.png","bugs-combat3.png","bugs-combat4.png"}){BufferedImage original=ImageIO.read(new File("private/calibration/"+file));BufferedImage im=new BufferedImage(960,540,BufferedImage.TYPE_INT_RGB);java.awt.Graphics2D g=im.createGraphics();g.setRenderingHint(java.awt.RenderingHints.KEY_INTERPOLATION,java.awt.RenderingHints.VALUE_INTERPOLATION_BILINEAR);g.drawImage(original,0,0,960,540,null);g.dispose();JSONArray found=matcher.find(im.getRGB(0,0,960,540,null,0,960),960,540,"combat");System.out.println("960px "+file+": "+found);if(found.length()!=3)throw new AssertionError("Production capture scale "+file);n++;}
 for(String file:new String[]{"city.png","menu.png","results.png"}){BufferedImage im=ImageIO.read(new File("private/calibration/"+file));if(matcher.find(im.getRGB(0,0,im.getWidth(),im.getHeight(),null,0,im.getWidth()),im.getWidth(),im.getHeight(),"combat").length()>0)throw new AssertionError("Non-combat cannot invent a battle squad "+file);n++;}
 BufferedImage fight=ImageIO.read(new File("private/calibration/phoenix-combat.png"));BufferedImage resized=new BufferedImage(960,540,BufferedImage.TYPE_INT_RGB);java.awt.Graphics2D graphics=resized.createGraphics();graphics.setRenderingHint(java.awt.RenderingHints.KEY_INTERPOLATION,java.awt.RenderingHints.VALUE_INTERPOLATION_BILINEAR);graphics.drawImage(fight,0,0,960,540,null);graphics.dispose();int hostiles=EnemyBars.count(resized.getRGB(0,0,960,540,null,0,960),960,540);System.out.println("Visible enemy bars: "+hostiles);if(hostiles<1||hostiles>4)throw new AssertionError("Combat health-bar count");n++;
 int[] blank=new int[960*540];if(EnemyBars.count(blank,960,540)!=0)throw new AssertionError("Blank frame cannot contain hostiles");n++;if(matcher.find(blank,960,540,"combat").length()!=0)throw new AssertionError("Blank HUD cannot invent a squad");n++;System.out.println(n+" context checks passed");}}
